#!/system/bin/sh
set -u
__a=''
__b=''
__s='80cf888780dcdc7f8ec2a3f0eb4b79e7'
__c=''
__h='bfa9210752374e03a2762136fc54d1ec0d0121271211c047810619d5e6af6b29'
__chk(){ { echo -n "$__a"; echo -n "$__b"; echo -n "$__s"; echo -n "$__c"; } | sha256sum 2>/dev/null | awk '{print $1}'; }
[ "$(__chk)" = "$__h" ] || { echo "[FATAL] integrity check failed - refusing to run"; exit 99; }
__key="$({ echo -n "$__a"; echo -n "$__s"; } | sha256sum 2>/dev/null | awk '{print $1}')"
__iv="$({ echo -n "$__a"; echo -n "$__s"; echo -n "iv"; } | sha256sum 2>/dev/null | awk '{print $1}' | cut -c1-32)"
eval "$({ echo -n "$__a"; } | base64 -d 2>/dev/null | gzip -dc 2>/dev/null)"
exit $?
